/** Look an element up or fail at boot — a missing id is a bug in index.html. */
function required<T extends Element>(id: string): T {
  const element = document.getElementById(id);
  if (element === null) {
    throw new Error(`index.html is missing #${id}`);
  }
  return element as unknown as T;
}

interface SecureContextVerdict {
  readonly usable: boolean;
  readonly reason: string;
}

/**
 * Why capture is or is not possible here.
 *
 * Both halves are checked, not just one: `isSecureContext` can be true while
 * `navigator.mediaDevices` is still absent (a browser without the API, or a
 * permissions policy that removed it), and reporting "insecure origin" in that
 * case would send the owner off minting a certificate that changes nothing.
 */
export function inspectSecureContext(view: Window = window): SecureContextVerdict {
  const secure = view.isSecureContext;
  const media = view.navigator.mediaDevices !== undefined;
  if (secure && media) {
    return { usable: true, reason: `secure context on ${view.location.origin}` };
  }
  if (!secure) {
    return {
      usable: false,
      reason:
        `${view.location.origin} is not a secure context, so navigator.mediaDevices is unavailable. ` +
        'localhost is exempt; a LAN address is not — serve the app over HTTPS with an mkcert ' +
        'certificate (host/README.md, ADR 0021 decision 8).',
    };
  }
  return {
    usable: false,
    reason:
      'This origin is a secure context but navigator.mediaDevices is absent — the browser does ' +
      'not expose the capture API here (an old browser, or a permissions policy that removed it).',
  };
}

/* --- small formatters. Kept pure and exported so they can be tested. -------- */

export function formatHz(hz: number): string {
  if (!Number.isFinite(hz)) {
    return '—';
  }
  return hz >= 1000 ? `${(hz / 1000).toFixed(3)} kHz` : `${hz.toFixed(2)} Hz`;
}

export function formatDb(db: number): string {
  return Number.isFinite(db) ? `${db.toFixed(2)} dB` : '—';
}

function flagWord(value: boolean | null): string {
  return value === null ? 'not reported' : value ? 'ON' : 'off';
}

/* --- state ---------------------------------------------------------------- */

interface Shell {
  summaries: readonly PresetSummary[];
  presets: Map<string, LivePreset>;
  selected: string | null;
  session: Session | null;
  startedAtMs: number | null;
  /** The one reference. Persisted; handed to every session; rendered before any. */
  reference: Reference | null;
  /** Did the last `store.save` succeed? `false` → "kept for this page only". */
  referencePersisted: boolean;
}

const shell: Shell = {
  summaries: [],
  presets: new Map(),
  selected: null,
  session: null,
  startedAtMs: null,
  reference: null,
  referencePersisted: true,
};

const store = createReferenceStore();

const frameListeners = new Set<(frame: FrameMessage) => void>();
const matchListeners = new Set<(match: MatchState | null) => void>();

/** The sentence for a preset whose `display.overlays` has no `f0`: nothing to match, nothing to capture. */
const NO_F0_OVERLAY = 'no pitch — this preset has no f0 overlay';

/** The glyph beside the match word. Shape, not colour: ✓ in, ▼ flat, ▲ sharp, — nothing to say. */
function matchGlyph(match: MatchState | null): string {
  if (match === null || match.cents === null) {
    return '—';
  }
  if (match.state === 'in') {
    return '✓';
  }
  return match.direction === 'flat' ? '▼' : '▲';
}

/* --- the cents bar's geometry, in the SVG's own units ------------------------ */

/** The axis runs 20…220 in `viewBox` units; its centre is 0 cents. */
const BAR = { left: 20, right: 220, centre: 120, halfWidth: 100, top: 8, height: 14 } as const;

/** x of a cents value on the bar: the mapping `barFraction` is defined for, applied to a fraction of the span. */
function barX(fractionOfSpan: number): number {
  return BAR.centre + fractionOfSpan * BAR.halfWidth;
}

function svgElement<K extends keyof SVGElementTagNameMap>(tag: K): SVGElementTagNameMap[K] {
  return document.createElementNS('http://www.w3.org/2000/svg', tag);
}

/* --- rendering ------------------------------------------------------------ */

function setStatus(text: string, kind: 'idle' | 'live' | 'error' = 'idle'): void {
  const state = required<HTMLElement>('capture-state');
  state.textContent = text;
  state.dataset['kind'] = kind;
}

function chainRow(term: string, detail: string, kind?: string): HTMLDivElement {
  const row = document.createElement('div');
  row.className = 'chain__row';
  const dt = document.createElement('dt');
  dt.textContent = term;
  const dd = document.createElement('dd');
  dd.textContent = detail;
  if (kind !== undefined) {
    dd.dataset['kind'] = kind;
  }
  row.append(dt, dd);
  return row;
}

function renderChain(session: Session | null): void {
  const list = required<HTMLElement>('capture-chain-readback');
  if (session === null) {
    list.replaceChildren(chainRow('state', 'idle — press Start capture'));
    return;
  }
  const c = session.chain;
  const rows: HTMLDivElement[] = [
    chainRow('device', c.deviceLabel),
    chainRow('preset rate', `${String(c.requestedSampleRate)} Hz (asserted, never resampled by us)`),
    chainRow('AudioContext rate', `${String(c.contextSampleRate)} Hz`),
    chainRow(
      'track rate',
      c.trackSampleRate === null ? 'not reported by this browser' : `${String(c.trackSampleRate)} Hz`,
    ),
  ];
  if (c.browserResampler !== null) {
    rows.push(chainRow('browser resampler', c.browserResampler, 'warn'));
  }
  rows.push(
    chainRow(
      'processing flags',
      `echoCancellation ${flagWord(c.processing.echoCancellation)} · ` +
        `noiseSuppression ${flagWord(c.processing.noiseSuppression)} · ` +
        `autoGainControl ${flagWord(c.processing.autoGainControl)}`,
      c.processing.allOff ? undefined : 'warn',
    ),
    chainRow(
      'base latency',
      c.baseLatencyS === null ? 'not reported' : `${(c.baseLatencyS * 1000).toFixed(2)} ms`,
    ),
    chainRow(
      'DC blocker',
      c.dcBlocker === null
        ? 'off for this preset'
        : `f_c ${String(c.dcBlocker.cutoffHz)} Hz · R = ${c.dcBlocker.R.toFixed(6)}`,
    ),
  );
  list.replaceChildren(...rows);
}

function renderCounters(): void {
  const target = required<HTMLElement>('counters');
  const session = shell.session;
  if (session === null) {
    target.textContent = '';
    return;
  }
  const s = session.stats();
  target.textContent =
    `${s.achievedColumnsPerS.toFixed(1)} columns/s achieved of ${s.expectedColumnsPerS.toFixed(1)} asked · ` +
    `${String(s.columnsDrawn)} drawn, ${String(s.columnsDropped)} dropped · ` +
    `${s.rafHz.toFixed(1)} Hz animation · ${s.elapsedS.toFixed(1)} s`;
}

function renderFrame(frame: FrameMessage): void {
  required<HTMLElement>('readout-peak').textContent =
    `${formatHz(frame.peak.hz)} at ${formatDb(frame.peak.db)}`;
  // The note is read from f0, never from the peak: the owner's first
  // screenshot (2026-08-22) showed a D3 labelled D4 because the strongest
  // partial was the second harmonic. With no estimator (the preset declares
  // no `f0` overlay) or no voicing, the cell says so rather than guessing.
  const f0 = frame.f0;
  const f0Cell = required<HTMLElement>('readout-f0');
  const noteCell = required<HTMLElement>('readout-note');
  if (f0 === null) {
    f0Cell.textContent = 'no f0 overlay';
    noteCell.textContent = '—';
  } else if (f0.f0Hz === null) {
    f0Cell.textContent = `unvoiced (clarity ${f0.clarity.toFixed(2)})`;
    noteCell.textContent = '—';
  } else {
    f0Cell.textContent = formatHz(f0.f0Hz);
    noteCell.textContent = formatNote(noteName(f0.f0Hz, A4_HZ));
  }
  renderPeakLegend(frame);
}

/**
 * Every marker's numbers, in full. The canvas skips a label that would
 * overprint its neighbour; this list is where nothing is skipped. The `li`s
 * are reused rather than rebuilt, because this runs at the hop rate.
 */
function renderPeakLegend(frame: FrameMessage): void {
  const list = required<HTMLUListElement>('peak-legend');
  const preset = shell.session?.preset;
  if (preset !== undefined && !preset.display.overlays.includes('peak_markers')) {
    list.replaceChildren(mutedItem('peak markers are not an overlay of this preset'));
    return;
  }
  if (frame.peaks.length === 0) {
    list.replaceChildren(mutedItem('none above the prominence floor'));
    return;
  }
  const reference = shell.reference;
  while (list.children.length > frame.peaks.length) {
    list.lastElementChild?.remove();
  }
  while (list.children.length < frame.peaks.length) {
    list.append(document.createElement('li'));
  }
  frame.peaks.forEach((peak, i) => {
    const item = list.children[i] as HTMLLIElement;
    item.className = '';
    item.textContent = legendLine(peak, frame.levelUnit, reference);
  });
}

function legendLine(peak: LabelledPeak, unit: string, reference: Reference | null): string {
  const label = peak.harmonic === null ? '—' : `H${String(peak.harmonic)}`;
  const live = `${label} ${formatHz(peak.hz)} ${peak.db.toFixed(1)} ${unit}`;
  if (reference === null || peak.harmonic === null) {
    return live;
  }
  // The reference's level at the SAME harmonic number, when its capture found
  // one: the timbre comparison the ghost trace shows, as a number.
  const twin = reference.peaks.find((p) => p.harmonic === peak.harmonic);
  return twin === undefined ? live : `${live} · ref ${twin.db.toFixed(1)}`;
}

function mutedItem(text: string): HTMLLIElement {
  const item = document.createElement('li');
  item.className = 'muted';
  item.textContent = text;
  return item;
}

/* --- the match cell and the cents bar ---------------------------------------- */

/**
 * Lay the bar out once, from the constants. The band edges and the ticks are
 * the only geometry that depends on a number, and that number is read from
 * the same frozen object the session matches against.
 */
function layoutCentsBar(): void {
  const { inTuneCents, nearCents, barSpanCents } = REFERENCE_CONSTANTS;
  const band = required<SVGRectElement>('cents-bar-band');
  const near = required<SVGRectElement>('cents-bar-near');
  const inLeft = barX(-inTuneCents / barSpanCents);
  const inRight = barX(inTuneCents / barSpanCents);
  band.setAttribute('x', String(inLeft));
  band.setAttribute('width', String(inRight - inLeft));
  const nearLeft = barX(-nearCents / barSpanCents);
  const nearRight = barX(nearCents / barSpanCents);
  near.setAttribute('x', String(nearLeft));
  near.setAttribute('width', String(nearRight - nearLeft));

  const ticks = required<SVGGElement>('cents-bar-ticks');
  ticks.replaceChildren();
  for (const c of [-barSpanCents, -nearCents, 0, nearCents, barSpanCents]) {
    const x = barX(c / barSpanCents);
    const line = svgElement('line');
    line.setAttribute('x1', String(x));
    line.setAttribute('x2', String(x));
    line.setAttribute('y1', String(BAR.top + BAR.height));
    line.setAttribute('y2', String(BAR.top + BAR.height + 3));
    const text = svgElement('text');
    text.setAttribute('x', String(x));
    text.setAttribute('y', String(BAR.top + BAR.height + 11));
    text.textContent = c === 0 ? '0' : `${c > 0 ? '+' : '−'}${String(Math.abs(c))}`;
    ticks.append(line, text);
  }
}

/**
 * The cell, from the session's `MatchState`. `off` is the shell's own state
 * for a preset with no estimator; every other value is the session's word.
 */
function renderMatch(match: MatchState | null, frame: FrameMessage | null): void {
  const cell = required<HTMLElement>('readout-match');
  const glyph = required<HTMLElement>('readout-match-glyph');
  const text = required<HTMLElement>('readout-match-text');
  const needle = required<SVGGElement>('cents-bar-needle');

  const estimatorOff = frame !== null && frame.f0 === null;
  if (estimatorOff) {
    cell.dataset['state'] = 'off';
    glyph.textContent = '—';
    text.textContent = NO_F0_OVERLAY;
    needle.dataset['visible'] = 'false';
    return;
  }

  cell.dataset['state'] = match === null ? 'none' : match.state;
  glyph.textContent = matchGlyph(match);
  text.textContent = describeMatch(match);
  const fraction = barFraction(match);
  if (fraction === null) {
    needle.dataset['visible'] = 'false';
    return;
  }
  needle.dataset['visible'] = 'true';
  needle.setAttribute('transform', `translate(${String(barX(fraction) - BAR.centre)} 0)`);
}

/* --- the reference cell and its controls --------------------------------------- */

function renderReference(): void {
  const cell = required<HTMLElement>('readout-reference');
  const warning = required<HTMLElement>('readout-reference-warning');
  const clear = required<HTMLButtonElement>('clear-reference');
  const reference = shell.reference;

  if (reference === null) {
    cell.textContent = 'none — hold a note, then press Capture reference';
    warning.hidden = true;
    warning.textContent = '';
    clear.disabled = true;
    return;
  }
  clear.disabled = false;
  const parts = [formatNote(reference.note), formatHz(reference.f0Hz)];
  if (reference.source === 'synthetic') {
    parts.push('(injected)');
  } else {
    parts.push(`±${reference.f0SpreadCents.toFixed(0)}¢ over ${String(reference.holdFrames)} frames`);
  }
  if (!shell.referencePersisted) {
    parts.push('kept for this page only');
  }
  cell.textContent = parts.join(' · ');

  // The SESSION's verdict, not a second call to `compatibility()` here: the
  // session decided whether to hand the ghost to the view from this same
  // object, so the warning and the missing ghost can never disagree.
  const verdict = shell.session?.compatibility() ?? null;
  if (verdict !== null && !verdict.comparable) {
    warning.textContent = verdict.message;
    warning.hidden = false;
  } else {
    warning.textContent = '';
    warning.hidden = true;
  }
}

/** The capture button and its hint, from the session's readiness. */
function renderReadiness(readiness: CaptureReadiness | null): void {
  const button = required<HTMLButtonElement>('capture-reference');
  const hint = required<HTMLElement>('reference-hint');
  const session = shell.session;
  if (session === null) {
    button.disabled = true;
    hint.textContent = `start capture, then hold a note for ${String(REFERENCE_CONSTANTS.holdFrames)} frames`;
    return;
  }
  if (!session.preset.display.overlays.includes('f0')) {
    button.disabled = true;
    hint.textContent = NO_F0_OVERLAY;
    return;
  }
  if (readiness === null) {
    button.disabled = true;
    hint.textContent = 'waiting for frames…';
    return;
  }
  button.disabled = !readiness.ready;
  hint.textContent = readiness.ready
    ? `hold steady — ${String(readiness.voicedFrames)} of ${String(readiness.framesHeld)} frames voiced, press to capture`
    : (readiness.refusal?.message ?? 'not ready');
}

/**
 * The conventions line. The hold's duration in seconds depends on the preset's
 * column rate, so it is quoted for the running preset, else the selected one,
 * else left as a frame count.
 */
function renderConstants(): void {
  const c = REFERENCE_CONSTANTS;
  const preset = shell.session?.preset ?? (shell.selected === null ? undefined : shell.presets.get(shell.selected));
  const holdSeconds = preset === undefined ? '' : ` = ${(c.holdFrames / expectedColumnsPerSecond(preset)).toFixed(2)} s`;
  required<HTMLElement>('constants-line').textContent =
    `A4 = ${String(A4_HZ)} Hz (prov.) · in tune ±${String(c.inTuneCents)} ¢ (prov.) · ` +
    `near ±${String(c.nearCents)} ¢ (prov.) · hold ${String(c.holdFrames)} frames${holdSeconds} (prov.) · ` +
    `K = ${String(DEFAULT_PEAK_PICKER.maxPeaks)} peaks (prov.)`;
}

/** Install a reference everywhere it is read: the shell, the store, the session, the cells. */
function installReference(reference: Reference | null): void {
  shell.reference = reference;
  shell.referencePersisted = reference === null ? store.clear() : store.save(reference);
  shell.session?.setReference(reference);
  renderReference();
  renderMatch(shell.session?.lastMatch() ?? matchState(null, reference), shell.session?.lastFrame() ?? null);
}

function captureReference(): CaptureResult {
  const session = shell.session;
  if (session === null) {
    throw new Error('capture needs a running session; press Start capture first');
  }
  const result = session.captureReference();
  if (isRefusal(result)) {
    required<HTMLElement>('reference-hint').textContent = result.message;
    return result;
  }
  installReference(result);
  return result;
}

function setReferenceF0(hz: number): Reference {
  const session = shell.session;
  let identity: { id: string; sha256: string };
  if (session !== null) {
    identity = session.referencePreset;
  } else {
    const summary = shell.summaries.find((p) => p.id === shell.selected);
    if (summary === undefined) {
      throw new Error('setReferenceF0 needs a running session or a selected preset');
    }
    identity = { id: summary.id, sha256: summary.sha256 };
  }
  const reference = syntheticReference(hz, identity);
  installReference(reference);
  return reference;
}

function renderClip(latched: boolean): void {
  const cell = required<HTMLElement>('readout-clip');
  cell.textContent = latched ? 'CLIP' : 'clear';
  cell.dataset['kind'] = latched ? 'clip' : 'clear';
}

function presetItem(preset: PresetSummary): HTMLLIElement {
  const item = document.createElement('li');
  item.className = 'preset';

  const radio = document.createElement('input');
  radio.type = 'radio';
  radio.name = 'preset';
  radio.id = `preset-${preset.id}`;
  radio.value = preset.id;
  radio.checked = preset.id === shell.selected;
  radio.addEventListener('change', () => {
    if (radio.checked) {
      shell.selected = preset.id;
      renderConstants();
    }
  });

  const label = document.createElement('label');
  label.className = 'preset__name';
  label.htmlFor = radio.id;
  label.textContent = preset.name;

  const targets = document.createElement('span');
  targets.className = 'preset__targets';
  targets.textContent = preset.targets.join(' · ');

  // The digest is the point of this list, so it is rendered in full rather than
  // truncated: a truncated hash is a hash nobody can compare against
  // `sha256sum protocols/presets/<id>.json`.
  const digest = document.createElement('code');
  digest.className = 'preset__sha';
  digest.textContent = preset.sha256;
  digest.title = `sha256 of ${String(preset.bytes)} bytes served at ${preset.url}`;

  item.append(radio, label, targets, digest);
  return item;
}

function errorItem(what: string, error: unknown): HTMLLIElement {
  const item = document.createElement('li');
  item.className = 'error';
  item.textContent =
    error instanceof ApiError
      ? `${what}: ${error.code} — ${error.message} (HTTP ${String(error.status)})`
      : `${what}: ${error instanceof Error ? error.message : String(error)}`;
  return item;
}

async function loadPresets(): Promise<void> {
  const list = required<HTMLUListElement>('preset-list');
  try {
    required<HTMLElement>('presets-provenance').textContent = `(${presetsSource.provenance})`;
    const summaries = await presetsSource.list();
    shell.summaries = summaries;
    // `live_singing` is the preset the founding document's waterfall is about,
    // so it is the one a visitor should land on. Falling back to the first
    // served id keeps this working if the set is ever edited.
    shell.selected =
      summaries.find((p) => p.id === 'live_singing')?.id ?? summaries[0]?.id ?? null;
    list.replaceChildren(...summaries.map(presetItem));

    // Sources are fetched as TEXT and parsed here; the digest shown above is
    // over the bytes, and this parse never feeds it (decision 7a).
    await Promise.all(
      summaries.map(async (summary) => {
        try {
          const source = await presetsSource.source(summary.id);
          shell.presets.set(summary.id, readLivePreset(JSON.parse(source)));
        } catch (error) {
          const note = document.createElement('li');
          note.className = 'error';
          note.textContent =
            error instanceof PresetRejected
              ? `${summary.id} rejected at ${error.pointer}: ${error.message}`
              : `${summary.id} unreadable: ${error instanceof Error ? error.message : String(error)}`;
          list.append(note);
        }
      }),
    );
  } catch (error) {
    list.replaceChildren(errorItem('presets unavailable', error));
  }
}

async function renderVersion(): Promise<void> {
  const target = required<HTMLElement>('backend-version');
  if (!presetsSource.capabilities.backend) {
    // A STATUS, never an error: on the owner's site there is no backend by
    // design, and a red "unreachable" would report a fault where there is none.
    // What matters to a reader is where the digests below came from.
    target.textContent = `standalone build — ${presetsSource.provenance}`;
    return;
  }
  try {
    const version = await api.getVersion();
    const api_ = version.api === undefined ? '' : ` · api ${version.api}`;
    target.textContent = `backend: ${version.version}${api_}`;
  } catch (error) {
    target.textContent =
      error instanceof ApiError
        ? `backend unreachable: ${error.code} (HTTP ${String(error.status)})`
        : `backend unreachable: ${error instanceof Error ? error.message : String(error)}`;
    target.classList.add('error');
  }
}

/* --- start / stop --------------------------------------------------------- */

let countersTimer: number | null = null;

async function start(presetId?: string): Promise<void> {
  if (shell.session !== null) {
    return;
  }
  const id = presetId ?? shell.selected;
  if (id === null) {
    setStatus('no preset selected', 'error');
    return;
  }
  const preset = shell.presets.get(id);
  if (preset === undefined) {
    setStatus(`preset ${id} was not loaded — see the preset list`, 'error');
    return;
  }
  const button = required<HTMLButtonElement>('capture-button');
  button.disabled = true;
  setStatus(`opening the microphone for ${preset.name}…`);
  try {
    const sha256 = shell.summaries.find((p) => p.id === id)?.sha256;
    shell.session = await startSession({
      preset,
      canvas: required<HTMLCanvasElement>('spectrum-canvas'),
      waterfallCanvas: required<HTMLCanvasElement>('waterfall-canvas'),
      ...(sha256 === undefined ? {} : { presetSha256: sha256 }),
      callbacks: {
        onChain: () => { renderChain(shell.session); },
        onFrame: (frame) => {
          renderFrame(frame);
          frameListeners.forEach((listener) => { listener(frame); });
        },
        onMatch: (match, frame) => {
          renderMatch(match, frame);
          matchListeners.forEach((listener) => { listener(match); });
        },
        onReadiness: renderReadiness,
        onClip: renderClip,
        onError: (message) => { setStatus(message, 'error'); },
      },
    });
    // The reference the shell already holds goes to the new session before its
    // first frame, so the ghost and the match are there from the first column.
    shell.session.setReference(shell.reference);
    shell.startedAtMs = performance.now();
    renderChain(shell.session);
    renderClip(false);
    renderReference();
    renderReadiness(null);
    renderConstants();
    setStatus(`live — ${preset.name}`, 'live');
    button.textContent = 'Stop capture';
    countersTimer = window.setInterval(renderCounters, 500);
  } catch (error) {
    // Three failures worth telling apart, because the fix differs: no API at
    // all, a rate the preset cannot accept, and a denied permission.
    if (error instanceof RateRefused) {
      setStatus(error.message, 'error');
    } else if (error instanceof CaptureUnavailable) {
      setStatus(error.message, 'error');
    } else if (error instanceof DOMException && error.name === 'NotAllowedError') {
      setStatus('microphone permission was denied — the browser blocked the request', 'error');
    } else {
      setStatus(`capture failed: ${error instanceof Error ? error.message : String(error)}`, 'error');
    }
  } finally {
    button.disabled = false;
  }
}

async function stop(): Promise<void> {
  const session = shell.session;
  if (session === null) {
    return;
  }
  shell.session = null;
  shell.startedAtMs = null;
  if (countersTimer !== null) {
    window.clearInterval(countersTimer);
    countersTimer = null;
  }
  await session.stop();
  renderChain(null);
  renderCounters();
  renderReference();
  renderReadiness(null);
  renderMatch(matchState(null, shell.reference), null);
  renderConstants();
  setStatus('idle — stopped');
  required<HTMLButtonElement>('capture-button').textContent = 'Start capture';
}

/* --- boot ----------------------------------------------------------------- */

function applySecureContextVerdict(verdict: SecureContextVerdict): boolean {
  const banner = required<HTMLElement>('insecure-banner');
  const detail = required<HTMLElement>('insecure-banner-detail');
  const button = required<HTMLButtonElement>('capture-button');

  if (verdict.usable) {
    banner.hidden = true;
    button.disabled = false;
    setStatus('idle — press Start capture');
    return true;
  }
  detail.textContent = verdict.reason;
  banner.hidden = false;
  button.disabled = true;
  setStatus('capture unavailable — insecure origin', 'error');
  return false;
}

/**
 * Light/dark, and the repaint a canvas needs that the DOM does not.
 *
 * A CSS custom property change restyles every DOM node for free; a canvas holds
 * pixels that were painted with the OLD values and will keep them until
 * something draws again. So the controller's subscription re-reads the palette
 * and forces a repaint — which is also why `refreshPalette` calls `resize()`
 * rather than waiting for the next frame: when capture is stopped there is no
 * next frame, and the axes would stay the previous theme's colour indefinitely.
 */
function wireTheme(): ThemeController {
  const controller = createThemeController();
  const toggle = required<HTMLButtonElement>('theme-toggle');
  const label = required<HTMLElement>('theme-toggle-label');

  if (controller.embedded) {
    // The surrounding page owns the setting; the control would be a lie.
    toggle.hidden = true;
  } else {
    toggle.hidden = false;
    toggle.addEventListener('click', () => { controller.cycle(); });
  }

  controller.subscribe((theme) => {
    label.textContent = `theme: ${controller.choice()}`;
    toggle.setAttribute('aria-label', `Theme: ${controller.choice()} (showing ${theme}). Click to change.`);
    shell.session?.refreshPalette();
  });
  return controller;
}

function main(): void {
  wireTheme();
  const usable = applySecureContextVerdict(inspectSecureContext());
  renderChain(null);

  const button = required<HTMLButtonElement>('capture-button');
  button.addEventListener('click', () => {
    void (shell.session === null ? start() : stop());
  });

  // The reference: load it, draw the bar's geometry, render the cells, and
  // wire the two buttons — all before any session, so a reload shows the note
  // that was captured yesterday and not an empty cell until capture starts.
  layoutCentsBar();
  shell.reference = store.load();
  renderReference();
  renderReadiness(null);
  renderMatch(matchState(null, shell.reference), null);
  renderConstants();
  required<HTMLButtonElement>('capture-reference').addEventListener('click', () => {
    captureReference();
  });
  required<HTMLButtonElement>('clear-reference').addEventListener('click', () => {
    installReference(null);
  });

  // Deliberately not awaited together with a failure that aborts the other:
  // a dead /api/version must not blank the preset list, and vice versa.
  void renderVersion();
  const ready = loadPresets().then(() => {
    if (usable) {
      required<HTMLElement>('capture-hint').textContent =
        'Your browser will ask for microphone permission. Nothing is uploaded.';
    }
    // Now that a preset is selected, the hold can be quoted in seconds too.
    renderConstants();
  });

  const host: DebugHost = {
    ready,
    current: () => shell.session,
    startedAtMs: () => shell.startedAtMs,
    presetIds: () => shell.summaries.map((p) => p.id),
    start,
    stop,
    onFrame: (listener) => {
      frameListeners.add(listener);
      return () => frameListeners.delete(listener);
    },
    reference: () => shell.reference,
    capture: captureReference,
    clearReference: () => { installReference(null); },
    setReferenceF0,
    match: () => shell.session?.lastMatch() ?? null,
    onMatch: (listener) => {
      matchListeners.add(listener);
      return () => matchListeners.delete(listener);
    },
    constants: (): DebugConstants => ({
      ...REFERENCE_CONSTANTS,
      a4Hz: A4_HZ,
      maxPeaks: DEFAULT_PEAK_PICKER.maxPeaks,
    }),
  };
  installDebugSurface(host);
}

main();
