// Periodic cosine-sum windows — the TypeScript side of ADR 0006 D1.
//
// This is a transcription of `host/src/spectral_host/spectrum.py`'s window
// section, function by function. Where that file makes a choice, this file
// makes the SAME choice and names the decision; where it deliberately differs
// (one place, `windowTable` below), the difference is measured and stated.
//
// THE TRAP THIS MODULE EXISTS TO CLOSE (ADR 0006 D1, measured 2026-08-21 with
// SciPy 1.18.0 at N = 4096): a window is NEVER built from a library's name for
// it. Four of the six preset families happen to match a SciPy name; two do not,
// in opposite directions — SciPy's `nuttall` IS this project's
// `blackman_nuttall`, and this project's `nuttall` has no SciPy name at all and
// differs from SciPy's by max |Δ| = 0.0163. A browser library window by name
// would carry the same class of silent error. Coefficients are the contract.
// ----------------------------------------------------------------------------

/**
 * The window coefficient table.
 *
 * SINGLE SOURCE: `protocols/specs/preset-schema.md` §4.3, the table headed
 * "`name` | a₀…a₄ | coherent_gain | coherent_gain_db | enbw_bins", copied digit
 * for digit (ADR 0006 D1: "the coefficient table lives in ONE place"). This is
 * the third language the table exists in (C, Python, TypeScript) and the fourth
 * copy counting the preset JSON — ADR 0006's consequence (−) names exactly that
 * cost. `tests/golden/window-digests.test.ts` parses §4.3 and fails if a digit
 * here drifts from it, which is what keeps the copy honest.
 *
 * `rect` is the seventh family: admitted by the golden manifest's
 * `$defs/window_family` for calibration tones only (ADR 0009 amendment, schema
 * "1.1"; ADR 0006 consequence (c)) and NEVER a preset family — a preset loader
 * that meets it must reject the preset. Order: the six §4.3 rows, then `rect`,
 * matching `spectral_host.spectrum.WINDOW_FAMILIES`.
 */
export const WINDOW_FAMILIES: Readonly<Record<string, readonly number[]>> = Object.freeze({
  hann: Object.freeze([0.5, 0.5]),
  blackman: Object.freeze([0.42, 0.5, 0.08]),
  blackman_harris: Object.freeze([0.35875, 0.48829, 0.14128, 0.01168]),
  blackman_nuttall: Object.freeze([0.3635819, 0.4891775, 0.1365995, 0.0106411]),
  nuttall: Object.freeze([0.355768, 0.487396, 0.144232, 0.012604]),
  flat_top: Object.freeze([0.21557895, 0.41663158, 0.277263158, 0.083578947, 0.006947368]),
  rect: Object.freeze([1.0]),
});

/** The families a PRESET may name — §4.3's six. `rect` is deliberately absent. */
export const PRESET_WINDOW_FAMILIES: readonly string[] = Object.freeze(
  Object.keys(WINDOW_FAMILIES).filter((f) => f !== 'rect'),
);

/** The §4.3 coefficients of `family`, as a fresh array (the table itself is never handed out). */
export function windowCoefficients(family: string): number[] {
  const a = WINDOW_FAMILIES[family];
  if (a === undefined) {
    throw new RangeError(
      `unknown window family ${JSON.stringify(family)}; expected one of ${Object.keys(WINDOW_FAMILIES).join(', ')}`,
    );
  }
  return [...a];
}

/** manifest.schema.yaml: `windows[].n` and `window_length_samples` have minimum 2. */
function checkWindowLength(n: number): void {
  if (!Number.isInteger(n) || n < 2) {
    throw new RangeError(`window length must be an integer >= 2 (manifest schema), got ${String(n)}`);
  }
}

function coefficientsOf(family: string | readonly number[]): readonly number[] {
  const a = typeof family === 'string' ? windowCoefficients(family) : family;
  if (a.length < 1) {
    throw new RangeError('a cosine-sum window needs at least one coefficient');
  }
  for (const c of a) {
    if (!Number.isFinite(c)) {
      throw new RangeError(`window coefficients must be finite, got ${String(c)}`);
    }
  }
  return a;
}

/**
 * The periodic cosine-sum window in float64: `w[j] = Σ_k (−1)^k a_k cos(2πkj/n)`.
 *
 * ADR 0006 D1's formula, verbatim — the length-`n` period, not the symmetric
 * `1/(n−1)` form. The symmetric form is NOT offered by this module and is not
 * an option anywhere in the pipeline: ADR 0006 D1 rejects it outright (its
 * NENBW no longer equals the closed form the presets ship — hann at N = 4096
 * gives 1.500366 instead of 1.5), and the oracle refuses to build it too
 * (`spectrum._window_for` raises on `fftbins: false`). The unit test builds a
 * symmetric hann of its OWN and asserts the two differ, so that nobody later
 * "fixes" the denominator to make a number look rounder.
 *
 * This is `general_cosine(n, a, sym=False)`. SciPy evaluates it as
 * `Σ_k a_k cos(k·fac_j)` with `fac_j = −π + j·2π/n`, which is the same
 * expression after `cos(kπ − θ) = (−1)^k cos θ`; the two differ only in
 * argument reduction. MEASURED 2026-08-22 for all seven families at n = 4096:
 * max |Δ| ≤ 4.44e-16 in float64 against SciPy, and ZERO samples differ after
 * the float32 rounding below — so the digest row is not at risk from the
 * choice of expression. (It is still at risk from `Math.cos` itself: V8's is
 * not the correctly-rounded glibc `cos`, and a 1-ULP float64 difference
 * survives the float32 rounding with probability ≈ 2⁻²⁸ per sample. The digest
 * test is the thing that would catch it; it is green today.)
 */
export function windowFloat64(family: string | readonly number[], n: number): Float64Array {
  checkWindowLength(n);
  const a = coefficientsOf(family);
  const w = new Float64Array(n);
  for (let k = 0; k < a.length; k += 1) {
    const ak = (k % 2 === 0 ? 1 : -1) * (a[k] as number);
    if (k === 0) {
      w.fill(ak);
      continue;
    }
    const step = (2 * Math.PI * k) / n;
    for (let j = 0; j < n; j += 1) {
      w[j] = (w[j] as number) + ak * Math.cos(step * j);
    }
  }
  return w;
}

/**
 * The float32 window table for `(family, n)` — the table this pipeline MULTIPLIES BY
 * and the table the digest HASHES, which are deliberately the same array.
 *
 * ADR 0021 decision 2: "the float64 table rounded **once** to float32 so the
 * digest is the device's". Rounded once, at this seam, and never again.
 *
 * ONE MEASURED DIVERGENCE FROM THE ORACLE, stated rather than hidden. The
 * Python oracle multiplies the frame by the *float64* window when the manifest
 * says `dtype: float64` (`spectrum._window_for`), so a TypeScript frame
 * windowed by the float32 table is not computing the identical expression.
 * MEASURED 2026-08-22 over all nineteen Tier-0 spectra, float32 table vs
 * float64 table through the whole ADR 0006 chain, on bins ≥ −80 dBFS:
 * worst-case **1.85e-5 dB** (`sine_440_m1dBFS_32k`), i.e. 540× inside the
 * 0.01 dB row of `docs/validation/golden-files.md`. The trade bought by
 * accepting it is that the digest row and the spectrum row are checked against
 * ONE array: a table that hashed correctly but multiplied differently would be
 * a window bug the digest row could not see.
 */
export function windowTable(family: string | readonly number[], n: number): Float32Array {
  return Float32Array.from(windowFloat64(family, n));
}

/**
 * The N float32 little-endian bytes of a window table — the digest's subject.
 *
 * The recipe of `manifest.schema.yaml` `windows[].sha256` and of
 * `docs/validation/golden-files.md`'s "exact" digest row:
 * `hashlib.sha256(np.asarray(w, dtype="<f4").tobytes()).hexdigest()`.
 * Written through a DataView with an explicit `littleEndian = true` rather than
 * by aliasing `table.buffer`: a typed-array view is PLATFORM endian, and the
 * manifest says little. Every machine this runs on today is little-endian,
 * which is exactly why the assumption would never be caught if it were wrong.
 */
export function windowTableBytes(table: Float32Array): Uint8Array {
  const bytes = new Uint8Array(table.length * 4);
  const view = new DataView(bytes.buffer);
  for (let j = 0; j < table.length; j += 1) {
    view.setFloat32(j * 4, table[j] as number, true);
  }
  return bytes;
}

/** `S1 = Σw`, `S2 = Σw²`, `NENBW = N·S2/S1²` [bins] — Heinzel 2002 (bibliography 05 #1), ADR 0006 D2. */
export interface WindowSums {
  readonly s1: number;
  readonly s2: number;
  readonly nenbw: number;
}

/**
 * The three sums of a window table, accumulated in double.
 *
 * The table is float32 (that is what the device holds and what the digest
 * hashes) but every element widens to double on read in JavaScript and the
 * accumulator is double — the same arithmetic `spectrum.window_sums` does when
 * the CLI hands it the float32 table. Summing 4096 float32 values in float32
 * would lose the low bits of S2 and shift every level; there is no reason to
 * reproduce that here, and the device's own float32 sum is a separate question
 * that the device's own tolerance row covers.
 */
export function windowSums(w: Float32Array | Float64Array): WindowSums {
  if (w.length < 1) {
    throw new RangeError('window must be a non-empty 1-D array');
  }
  let s1 = 0;
  let s2 = 0;
  for (let j = 0; j < w.length; j += 1) {
    const v = w[j] as number;
    s1 += v;
    s2 += v * v;
  }
  if (s1 === 0) {
    throw new RangeError('window sums to zero; NENBW is undefined');
  }
  return { s1, s2, nenbw: (w.length * s2) / (s1 * s1) };
}

/**
 * NENBW of a PERIODIC cosine-sum window from its coefficients alone.
 *
 * ADR 0006 D2: orthogonality gives `S1 = N·a₀` and `S2 = N·(a₀² + Σ_{k≥1} a_k²/2)`
 * EXACTLY, hence `NENBW = (a₀² + Σ_{k≥1} a_k²/2)/a₀²` — which is precisely the
 * `enbw_bins` each preset ships (preset-schema.md §4.3). It is a closed form,
 * so it tests the window without a reference implementation existing; the
 * SYMMETRIC form does not satisfy it, and that is the argument for periodic.
 */
export function nenbwClosedForm(coefficients: readonly number[]): number {
  const a = coefficientsOf(coefficients);
  const a0 = a[0] as number;
  if (a0 === 0) {
    throw new RangeError('a cosine-sum window needs a non-zero a0');
  }
  let sum = 0;
  for (let k = 1; k < a.length; k += 1) {
    const ak = a[k] as number;
    sum += (ak * ak) / 2;
  }
  return (a0 * a0 + sum) / (a0 * a0);
}

/** `coherent_gain` of §4.3: a₀. Divide a TONE's magnitude by this (never a noise power). */
export function coherentGain(coefficients: readonly number[]): number {
  return coefficientsOf(coefficients)[0] as number;
}

/** Equivalent noise bandwidth in Hz: `ENBW = NENBW · fs / N` (ADR 0006 D2; preset-schema.md §4.4). */
export function enbwHz(nenbw: number, fs: number, n: number): number {
  if (!(fs > 0) || !(n > 0)) {
    throw new RangeError('fs and n must be positive');
  }
  return (nenbw * fs) / n;
}
