//
// Light/dark, and the one thing the Delta simulator embed got wrong.
//
// This application is served two ways. Standalone on a laptop or a phone, where
// it owns the page and follows the operating system unless told otherwise; and
// inside an iframe on alexander-gomez.com, where it owns nothing and must
// follow whatever the surrounding page decided. The Delta embed does not do the
// second, so it stays light while the site around it goes dark — the visible
// seam this file exists to avoid.
//
// HOW THE MIRROR WORKS, AND WHY NOT postMessage. al-folio's `assets/js/theme.js`
// writes `data-theme` on its own `<html>`. Same-origin iframes can read the
// parent document, so a `MutationObserver` on that attribute is enough: no
// script has to be added to the site, and nothing breaks if the site is
// rebuilt. A `SecurityError` means the frame is cross-origin, and the
// controller silently becomes a standalone one — which is also what happens
// when someone opens `/assets/superspectral/index.html` directly.
//
// THE STORAGE KEY IS `superspectral.theme`, NOT `theme`. al-folio owns `theme`
// on that origin. Writing it from inside the iframe would change the whole
// site's setting from a control that looks local, and reading it would make the
// standalone page inherit a preference expressed about a different page.
// ---------------------------------------------------------------------------

/** The user's choice. `system` is a choice too — it means "keep following the OS". */
export type ThemeChoice = 'light' | 'dark' | 'system';

/** What actually gets painted. `system` has been resolved away. */
export type Theme = 'light' | 'dark';

export const STORAGE_KEY = 'superspectral.theme';

/** The order the toggle walks. Ends where it started, so the control is reversible. */
export const CYCLE: readonly ThemeChoice[] = Object.freeze(['system', 'light', 'dark']);

/** Anything that is not one of the three is `system` — a corrupt key must not brick the page. */
export function parseChoice(raw: unknown): ThemeChoice {
  return raw === 'light' || raw === 'dark' || raw === 'system' ? raw : 'system';
}

export function resolveTheme(choice: ThemeChoice, prefersDark: boolean): Theme {
  if (choice === 'system') {
    return prefersDark ? 'dark' : 'light';
  }
  return choice;
}

export function nextChoice(choice: ThemeChoice): ThemeChoice {
  const index = CYCLE.indexOf(choice);
  return CYCLE[(index + 1) % CYCLE.length] as ThemeChoice;
}

export interface ThemeController {
  /** The resolved theme in effect. */
  theme(): Theme;
  /** The user's stored choice; always `system` while embedded (the parent decides). */
  choice(): ThemeChoice;
  /** Is this controller following a parent document rather than the OS? */
  readonly embedded: boolean;
  /** Advance the toggle. A no-op while embedded. */
  cycle(): void;
  /** Called immediately with the current theme, then on every change. Returns an unsubscribe. */
  subscribe(listener: (theme: Theme) => void): () => void;
  destroy(): void;
}

/** The parent's `<html>`, or `null` when there is no accessible parent. */
export function parentRoot(view: Window): HTMLElement | null {
  if (view.parent === view) {
    return null;
  }
  try {
    // Touching `.document` is what throws on a cross-origin parent, so the read
    // and the guard have to be the same expression.
    return view.parent.document.documentElement;
  } catch {
    return null;
  }
}

function readStored(view: Window): ThemeChoice {
  try {
    return parseChoice(view.localStorage.getItem(STORAGE_KEY));
  } catch {
    // Storage can throw outright: Safari in private mode, and any browser with
    // third-party storage blocked — which an iframe on someone else's site is.
    return 'system';
  }
}

function writeStored(view: Window, choice: ThemeChoice): void {
  try {
    view.localStorage.setItem(STORAGE_KEY, choice);
  } catch {
    // A preference that cannot be persisted still applies for this page view.
  }
}

export function createThemeController(view: Window = window): ThemeController {
  const root = view.document.documentElement;
  const parent = parentRoot(view);
  const embedded = parent !== null;
  const media = view.matchMedia('(prefers-color-scheme: dark)');

  let choice: ThemeChoice = embedded ? 'system' : readStored(view);
  let current: Theme = 'light';
  const listeners = new Set<(theme: Theme) => void>();

  function parentTheme(): Theme | null {
    const declared = parent?.getAttribute('data-theme');
    return declared === 'dark' || declared === 'light' ? declared : null;
  }

  function compute(): Theme {
    // Embedded: the parent's explicit choice wins; if the parent has not
    // stamped one yet (its theme.js runs on DOMContentLoaded), fall through to
    // the OS, which is the same answer its own default would give.
    return parentTheme() ?? resolveTheme(choice, media.matches);
  }

  function apply(): void {
    const next = compute();
    root.setAttribute('data-theme', next);
    root.setAttribute('data-theme-setting', embedded ? 'system' : choice);
    if (next === current) {
      return;
    }
    current = next;
    listeners.forEach((listener) => { listener(current); });
  }

  const onMedia = (): void => { apply(); };
  media.addEventListener('change', onMedia);

  // `MutationObserver` off the global rather than off `view`: the DOM lib does
  // not declare it as a `Window` property, and the constructor is the same one
  // in every realm this code runs in (the frame's own).
  const observer = parent === null ? null : new MutationObserver(() => { apply(); });
  observer?.observe(parent as Node, { attributes: true, attributeFilter: ['data-theme'] });

  // Set the attribute before anyone subscribes, so the first paint is themed.
  root.setAttribute('data-theme', compute());
  current = compute();
  root.setAttribute('data-theme-setting', embedded ? 'system' : choice);

  return {
    theme: () => current,
    choice: () => choice,
    embedded,
    cycle: () => {
      if (embedded) {
        return;
      }
      choice = nextChoice(choice);
      writeStored(view, choice);
      apply();
    },
    subscribe: (listener) => {
      listeners.add(listener);
      listener(current);
      return () => listeners.delete(listener);
    },
    destroy: () => {
      media.removeEventListener('change', onMedia);
      observer?.disconnect();
      listeners.clear();
    },
  };
}
