//
// Where the six presets come from — and the one exception to "never ship a copy".
//
// ADR 0021 decision 7(a): the files under `protocols/presets/` are the single
// source of truth, the backend serves their BYTES verbatim, and the front end
// never ships its own copy. That rule assumes a backend. The standalone build
// the owner's Jekyll site hosts has none: it is a directory of static files
// under `assets/superspectral/`, and a fetch to `/api/presets` there is a 404.
//
// So the site build embeds the six canonical files AS RAW BYTES at build time —
// `?raw`, never `import ... from './x.json'`, which would parse and re-serialise
// and produce different bytes for the same preset. It then hashes them AT
// RUNTIME, in the browser, with the same `sha256` the backend path displays, and
// shows the digest in the same place. What a visitor compares against
// `sha256sum protocols/presets/live_singing.json` is a number this page computed,
// not one it was told.
//
// Three guards keep that honest, and all three are mechanical:
//
//   * `tests/unit/bundled-presets-match-disk.test.ts` — the embedded text equals
//     the file on disk, byte for byte, trailing newline included, and its digest
//     equals `protocols/presets/SHA256SUMS`.
//   * `scripts/check-no-bundled-presets.mjs` — the BACKEND build (`npm run build`)
//     contains no preset id, no digest and no `schema_version` anywhere. This is
//     the structural proof that decision 7(a) still holds where it always did.
//   * `scripts/check-site-bundle.mjs` — the site build DOES contain them.
//
// The branch is chosen by a compile-time constant so Rollup drops the other one
// entirely. A runtime `if` would leave both in the bundle, and the backend build
// would then contain preset bytes — failing the check above, correctly.
// ---------------------------------------------------------------------------

import type { PresetSummary } from './client';

declare const __SPECTRAL_STANDALONE__: boolean;

export interface PresetsSource {
  /** The list, with a digest per row. */
  list(): Promise<readonly PresetSummary[]>;
  /** The canonical file as TEXT — bytes, not a re-serialised object. */
  source(id: string): Promise<string>;
  /** What this build can do. The offline pane and /api/golden need a backend. */
  readonly capabilities: { readonly backend: boolean };
  /** Shown in the interface so a reader knows which of the two paths produced the digests. */
  readonly provenance: string;
}

export const STANDALONE: boolean =
  typeof __SPECTRAL_STANDALONE__ === 'boolean' ? __SPECTRAL_STANDALONE__ : false;

/**
 * The source this build uses.
 *
 * A top-level `await import()` rather than a static import of both: the
 * condition is a compile-time constant, so Rollup evaluates it, keeps one branch
 * and drops the other from the graph entirely. That is what makes
 * `check-no-bundled-presets.mjs` a real proof rather than a hopeful grep.
 */
export const presets: PresetsSource = STANDALONE
  ? (await import('./presets-bundled')).bundledPresets
  : (await import('./presets-backend')).backendPresets;
