//
// The live session: the one place that owns a running capture.
//
// Everything below it is a pure or single-purpose module — `openCapture` opens
// a microphone, `spectrum.worker.ts` transforms a hop, `spectrum-view.ts`
// paints a column. None of them knows about the others. This file is the wire
// between them, and it is deliberately the ONLY file that holds the three at
// once, so that "what is running right now" has a single answer.
//
// THE ORDER OF TEARDOWN IS LOAD-BEARING. Stop the worklet's port first, then
// the worker, then the tracks, then the context. Reversed, a hop posted between
// `context.close()` and the port handler being detached lands on a worker whose
// `postMessage` target is gone, and the browser reports it as an unhandled
// rejection with no stack that points here.
//
// COUNTERS ARE MEASURED, NOT DERIVED. `expectedColumnsPerSecond` is what the
// preset ASKS for (`fs/hop`); `achievedColumnsPerSecond` is frames actually
// posted divided by elapsed wall time. ADR 0021 decision 3 forbids quoting
// either as a property of the watch, and the whole point of keeping both is
// that the gap between them is visible rather than assumed away.
//
// THE REFERENCE LIVES HERE TOO, BUT IS NOT BORN HERE. "Capture a note, then
// reach it" (ADR 0021 decision 1 note, 2026-08-22; roadmap Q54) needs the last
// `holdFrames` frames kept somewhere, and the session is the only object that
// sees every frame. So it keeps a ring of them and hands the ring to
// `app/reference.ts` — the pure module that decides whether the hold is
// capturable, what its median f0 is, and how far the live f0 is from it. This
// file never computes a cents figure: `onMatch` relays what `matchState`
// returned, per frame, and `onReadiness` what `captureReadiness` returned,
// every fifth frame (the button's enabled state does not need 50 Hz).
//
// The ring holds the `FrameMessage` objects themselves. Every array in one of
// them is a FRESH allocation the Worker transferred and never touches again
// (`protocol.ts`, `frameTransferables`), so holding twenty-five of them aliases
// nothing that can change under the capture — which is the property a block
// mean of raw periodograms (ADR 0006 D8) needs from its inputs.
//
// The ghost is drawn only when the reference is COMPARABLE with the running
// preset (`compatibility`): a spectrum averaged at N = 4096 on one window and
// scaling has no place on the axes of N = 8192 on another. The pitch is still
// compared — a cents figure is a ratio of two frequencies and does not care
// which preset measured either — so the match cell keeps working and the
// reference cell carries the warning instead.
// ---------------------------------------------------------------------------

import { dcBlockerPole } from '../dsp/dcblock';
import { defaultMpmParams } from '../dsp/mpm';
import { DEFAULT_PEAK_PICKER } from '../dsp/peaks';
import { DEFAULT_FLOOR_DB } from '../dsp/scale';
import {
  CaptureUnavailable,
  RateRefused,
  openCapture,
  type CaptureOptions,
  type OpenCapture,
} from '../audio/capture';
import type { CaptureChain } from '../audio/chain';
import { createSpectrumView, type SpectrumView } from '../render/spectrum-view';
import { createWaterfallView, type WaterfallView } from '../render/waterfall-view';
import { readSpectrumPalette, type SpectrumPalette } from '../render/palette';
import {
  expectedColumnsPerSecond,
  spectrumConfigFromPreset,
  type LivePreset,
} from './preset';
import type { FrameMessage, WorkerResponse } from '../worker/protocol';
import {
  REFERENCE_CONSTANTS,
  captureReadiness,
  captureReference,
  compatibility,
  isRefusal,
  matchState,
  type CaptureReadiness,
  type CaptureResult,
  type Compatibility,
  type MatchState,
  type Reference,
  type ReferencePreset,
} from './reference';

export { CaptureUnavailable, RateRefused };

/** How often `onReadiness` fires, in frames. The button does not need the hop rate. */
const READINESS_EVERY_N_FRAMES = 5;

/** Counters a harness and the status strip both read. All measured. */
export interface SessionStats {
  readonly framesPosted: number;
  readonly columnsDrawn: number;
  readonly columnsDropped: number;
  /** `fs/hop` — what the preset asks for. */
  readonly expectedColumnsPerS: number;
  /** framesPosted / elapsed — what this machine actually did. */
  readonly achievedColumnsPerS: number;
  /** Animation callbacks per second, rolling. */
  readonly rafHz: number;
  /** Has any hop ever reached full scale in this session? Latched here, not in the Worker. */
  readonly clipLatched: boolean;
  /** How many hops did. */
  readonly clipHops: number;
  readonly elapsedS: number;
}

export interface SessionCallbacks {
  /** The capture chain, once, as soon as the stream is open. */
  readonly onChain?: (chain: CaptureChain) => void;
  /** Every frame, after the view has been given it. Keep it cheap: this runs at the hop rate. */
  readonly onFrame?: (frame: FrameMessage) => void;
  /** A refusal or a worker error, as a sentence for the status strip. */
  readonly onError?: (message: string, cause?: unknown) => void;
  /** Clip state changed (false → true only; the latch never clears within a session). */
  readonly onClip?: (latched: boolean) => void;
  /**
   * Every frame, after `onFrame`: the live f0 against the reference, or `null`
   * while there is no reference. Computed by `reference.ts`'s `matchState`.
   */
  readonly onMatch?: (match: MatchState | null, frame: FrameMessage) => void;
  /** Every fifth frame: whether the ring could be captured now, with the numbers, and if not why. */
  readonly onReadiness?: (readiness: CaptureReadiness) => void;
}

export interface Session {
  readonly preset: LivePreset;
  readonly chain: CaptureChain;
  readonly view: SpectrumView;
  readonly waterfall: WaterfallView;
  stats(): SessionStats;
  resetCounters(): void;
  /** The most recent frame, or `null`. The object itself — copy before handing it out. */
  lastFrame(): FrameMessage | null;
  /** Re-read the palette from CSS and repaint. Called when the theme changes. */
  refreshPalette(palette?: SpectrumPalette): void;
  /**
   * Capture the ring as a reference (`reference.ts`'s `captureReference`).
   * On success the result is also installed as this session's reference, so
   * the next frame is already matched against it.
   */
  captureReference(): CaptureResult;
  /** Install (or remove) the reference the match and the ghost are drawn against. */
  setReference(reference: Reference | null): void;
  reference(): Reference | null;
  /** The match of the most recent frame, or `null` with no reference or no frame yet. */
  lastMatch(): MatchState | null;
  /** Whether the installed reference may be drawn as a ghost on this preset's axes; `null` with none. */
  compatibility(): Compatibility | null;
  /** The ring, oldest first. The objects themselves; see the header on why that is safe. */
  recentFrames(): readonly FrameMessage[];
  /** The preset as `reference.ts` sees it: id, digest and the axes the ghost is only comparable on. */
  readonly referencePreset: ReferencePreset;
  stop(): Promise<void>;
}

export interface StartSessionOptions {
  readonly preset: LivePreset;
  readonly canvas: HTMLCanvasElement;
  /** The waterfall's own canvas. Absent in a test that only wants the spectrum. */
  readonly waterfallCanvas?: HTMLCanvasElement;
  readonly callbacks?: SessionCallbacks;
  /** Injected by tests; the real one is built from `import.meta.url`. */
  readonly makeWorker?: () => Worker;
  /**
   * sha256 of the preset's served bytes (`PresetSummary.sha256`), recorded in a
   * captured reference so a later session can tell "same preset id, different
   * bytes" from "same preset". Absent in a test that has no summary; an empty
   * digest then matches only another empty digest.
   */
  readonly presetSha256?: string;
}

function defaultWorker(): Worker {
  // `new URL(..., import.meta.url)` with a literal path is the form Vite
  // statically analyses; a computed specifier emits nothing and the built
  // bundle 404s at runtime — which is exactly the failure that looks like
  // "works in dev, blank in production".
  return new Worker(new URL('../worker/spectrum.worker.ts', import.meta.url), {
    type: 'module',
    name: 'spectral-spectrum',
  });
}

export async function startSession(options: StartSessionOptions): Promise<Session> {
  const { preset, canvas } = options;
  const callbacks = options.callbacks ?? {};

  const captureOptions: CaptureOptions = {
    sampleRateHz: preset.sampleRateHz,
    windowLength: preset.fftSize,
    hopSamples: preset.hopSamples,
    dcBlocker:
      preset.dcBlockerHz === null
        ? null
        : { cutoffHz: preset.dcBlockerHz, R: dcBlockerPole(preset.dcBlockerHz, preset.sampleRateHz) },
  };

  // Capture FIRST. If the rate is refused or permission is denied there is no
  // worker to tear down and no canvas state to undo — the failure is one throw
  // out of one call, which is why this is not started in parallel with the
  // worker even though it would shave a few milliseconds.
  const capture: OpenCapture = await openCapture(captureOptions);
  callbacks.onChain?.(capture.chain);

  const worker = (options.makeWorker ?? defaultWorker)();
  const axes = {
    freqMinHz: preset.display.freqMinHz,
    freqMaxHz: preset.display.freqMaxHz,
    freqScale: preset.display.freqScale,
    dbFloor: preset.display.dbFloorDbfs,
    dbCeiling: preset.display.dbCeilingDbfs,
  };
  const view = createSpectrumView(canvas, readSpectrumPalette(canvas), axes);
  // The waterfall shares the preset's axes exactly, so a peak in the spectrum
  // and the stripe under it line up on the frequency axis. A second set of
  // limits here would be a second instrument.
  const waterfall = createWaterfallView(
    options.waterfallCanvas ?? document.createElement('canvas'),
    axes,
  );

  let framesPosted = 0;
  let clipHops = 0;
  let clipLatched = false;
  let last: FrameMessage | null = null;
  const startedAtMs = performance.now();
  let stopped = false;

  const referencePreset: ReferencePreset = {
    id: preset.id,
    sha256: options.presetSha256 ?? '',
    sampleRateHz: preset.sampleRateHz,
    fftSize: preset.fftSize,
    freqMinHz: preset.display.freqMinHz,
    freqMaxHz: preset.display.freqMaxHz,
  };
  /** The last `holdFrames` frames, oldest first. */
  const ring: FrameMessage[] = [];
  let reference: Reference | null = null;
  let referenceCompatibility: Compatibility | null = null;
  let lastMatch: MatchState | null = null;

  function installReference(next: Reference | null): void {
    reference = next;
    referenceCompatibility = next === null ? null : compatibility(next, referencePreset);
    // The ghost only on comparable axes; the pitch regardless (see the header).
    view.setReference(referenceCompatibility?.comparable === true ? next : null);
    lastMatch = next === null || last === null ? null : matchState(last.f0, next);
  }

  worker.postMessage({
    type: 'configure',
    config: spectrumConfigFromPreset(preset),
    sampleRateHz: preset.sampleRateHz,
    smoothing: preset.smoothing,
    dcBlockerHz: preset.dcBlockerHz,
    // The ARITHMETIC floor, not the preset's display floor.
    //
    // Clamping here looked harmless — a column drawn against a −90 dBFS axis
    // gains nothing from bins at −187 — and it is wrong, because the Worker's
    // output is DATA before it is a drawing. The first real-microphone run
    // (2026-08-22) reported the room's noise floor as exactly −90.0 dBFS in the
    // 2–8 kHz band, which is not a measurement of the room: it is the clamp,
    // reading back its own value. Anything quieter than the display floor —
    // a quiet room, the `room_noise_floor` preset's whole subject, the residual
    // against a golden — was being destroyed before it could be measured.
    //
    // The view clamps for drawing (`dbFloor`/`dbCeiling` in its options). That
    // is where a display decision belongs.
    floorDb: DEFAULT_FLOOR_DB,
    hold: preset.hold,
    freqMinHz: preset.display.freqMinHz,
    freqMaxHz: preset.display.freqMaxHz,
    // The preset decides which branches run. `f0` is an overlay only
    // `live_singing` and `sustained_pitch_lab` declare; under the others the
    // match cell says so rather than estimating a pitch nobody asked for.
    // Spread conditionally: exactOptionalPropertyTypes distinguishes an absent
    // key from an explicit undefined.
    ...(preset.display.overlays.includes('f0') ? { f0: defaultMpmParams(preset.sampleRateHz) } : {}),
    ...(preset.display.overlays.includes('peak_markers') ? { peaks: DEFAULT_PEAK_PICKER } : {}),
  });

  worker.onmessage = (event: MessageEvent<WorkerResponse>): void => {
    const message = event.data;
    if (message.type === 'error') {
      callbacks.onError?.(message.message);
      return;
    }
    framesPosted += 1;
    last = message;
    if (message.clipped) {
      clipHops += 1;
      if (!clipLatched) {
        clipLatched = true;
        callbacks.onClip?.(true);
      }
    }
    view.draw(message);
    // Every frame reaches the waterfall, not only the drawn ones: the spectrum
    // may drop a column to the animation rate, but the spectrogram is a RECORD
    // and a dropped row is a hole in time.
    waterfall.push(message);
    callbacks.onFrame?.(message);

    // The ring, then the match, then — every fifth frame — the readiness.
    ring.push(message);
    if (ring.length > REFERENCE_CONSTANTS.holdFrames) {
      ring.shift();
    }
    lastMatch = reference === null ? null : matchState(message.f0, reference);
    callbacks.onMatch?.(lastMatch, message);
    if (framesPosted % READINESS_EVERY_N_FRAMES === 0) {
      callbacks.onReadiness?.(captureReadiness(ring));
    }
  };

  worker.onerror = (event: ErrorEvent): void => {
    callbacks.onError?.(`the transform worker failed: ${event.message}`, event);
  };

  // The worklet's hop, relayed to the worker with the sample buffer
  // TRANSFERRED. The worklet allocates a fresh array per hop precisely so this
  // is safe; transferring an array the worklet still owned would zero it under
  // the audio thread.
  capture.node.port.onmessage = (event: MessageEvent): void => {
    if (stopped) {
      return;
    }
    const hop = event.data as {
      samples: Float32Array;
      frameIndex: number;
      capturedAtMs: number;
      peakAbs: number;
    };
    worker.postMessage(
      {
        type: 'hop',
        samples: hop.samples,
        frameIndex: hop.frameIndex,
        capturedAtMs: hop.capturedAtMs,
        peakAbs: hop.peakAbs,
      },
      [hop.samples.buffer],
    );
  };

  const resize = (): void => {
    view.resize();
    waterfall.resize();
  };
  const observer =
    typeof ResizeObserver === 'function' ? new ResizeObserver(() => { resize(); }) : null;
  observer?.observe(canvas);
  if (options.waterfallCanvas !== undefined) {
    observer?.observe(options.waterfallCanvas);
  }
  view.resize();
  waterfall.resize();

  return {
    preset,
    chain: capture.chain,
    view,
    waterfall,
    lastFrame: () => last,
    captureReference: (): CaptureResult => {
      const result = captureReference(ring, referencePreset);
      if (!isRefusal(result)) {
        installReference(result);
      }
      return result;
    },
    setReference: installReference,
    reference: () => reference,
    lastMatch: () => lastMatch,
    compatibility: () => referenceCompatibility,
    recentFrames: () => [...ring],
    referencePreset,
    refreshPalette: (palette?: SpectrumPalette) => {
      view.setPalette(palette ?? readSpectrumPalette(canvas));
      view.resize();
    },
    resetCounters: () => {
      framesPosted = 0;
      clipHops = 0;
      view.resetCounters();
    },
    stats: (): SessionStats => {
      const elapsedS = Math.max((performance.now() - startedAtMs) / 1000, 1e-9);
      return {
        framesPosted,
        columnsDrawn: view.columnsDrawn,
        columnsDropped: view.columnsDropped,
        expectedColumnsPerS: expectedColumnsPerSecond(preset),
        achievedColumnsPerS: framesPosted / elapsedS,
        rafHz: view.rafHz(),
        clipLatched,
        clipHops,
        elapsedS,
      };
    },
    stop: async (): Promise<void> => {
      if (stopped) {
        return;
      }
      stopped = true;
      // Order matters; see the header.
      capture.node.port.onmessage = null;
      worker.onmessage = null;
      worker.onerror = null;
      worker.terminate();
      observer?.disconnect();
      view.destroy();
      waterfall.destroy();
      await capture.close();
    },
  };
}
