//
// The preset, read once, into the shape the live path needs — and REFUSED
// rather than coerced when it does not say what it must.
//
// WHY A READER AND NOT A CAST. ADR 0010 decision 7 is "reject, never coerce",
// and ADR 0021 decision 7(a) makes the served file the single source of truth:
// "the front end never ships its own copy and the bundler never embeds one;
// drift is a red test, not a fork." A `JSON.parse(...) as Preset` would satisfy
// the type checker and satisfy nothing else — the first preset with a missing
// `hop_samples` would reach the AudioWorklet as `NaN` and produce a silent,
// empty spectrogram.
//
// THE RULE V8 CHECK IS THE ONE THAT EARNS ITS KEEP. ADR 0006 D1: windows are
// built from the PRESET'S OWN COEFFICIENTS, never by name, because
// `get_window("nuttall")` is a different window from esp-dsp's `nuttall` by
// 0.0163 — "any convention that routes through a *name* rather than through
// *coefficients* has a silent 0.0163 error in it". `dsp/window.ts` holds the
// §4.3 table and is keyed by name, exactly as `spectral_core` compiles its
// table in; so this reader does what the firmware loader does under rule V8 —
// it ASSERTS the preset's coefficients against that table and refuses on a
// mismatch. The check is the reason a name-keyed table is safe here.
// ----------------------------------------------------------------------------

import type { SpectrumConfig } from '../dsp/pipeline';
import { DEFAULT_INT16_SCALE } from '../dsp/scale';
import { PRESET_WINDOW_FAMILIES, windowCoefficients } from '../dsp/window';

/** The preset failed a rule. Carries the pointer so the message names the field. */
export class PresetRejected extends Error {
  readonly pointer: string;
  constructor(pointer: string, message: string) {
    super(`${pointer}: ${message}`);
    this.name = 'PresetRejected';
    this.pointer = pointer;
  }
}

/** The subset of a preset the live path uses, with every value already checked. */
export interface LivePreset {
  readonly id: string;
  readonly name: string;
  readonly sampleRateHz: number;
  readonly fftSize: number;
  readonly hopSamples: number;
  readonly intervalMs: number;
  readonly smoothing: number;
  readonly averaging: string;
  /** `analysis.spectrum_type` mapped onto the manifest's `scaling` enum. */
  readonly scaling: 'power_spectrum' | 'power_spectral_density';
  readonly dcBlockerHz: number | null;
  readonly hold: 'none' | 'peak';
  /** The preset's own `hold` before this application mapped it. `min` is not implemented in W1. */
  readonly holdRequested: string;
  readonly windowName: string;
  readonly windowCoefficients: readonly number[];
  readonly display: {
    readonly freqMinHz: number;
    readonly freqMaxHz: number;
    readonly freqScale: 'log' | 'linear';
    readonly dbFloorDbfs: number;
    readonly dbCeilingDbfs: number;
    readonly refreshHzTarget: number | null;
    /** `display.overlays`, verbatim — the schema's enum (≤ 8, unique). Which branches the Worker runs. */
    readonly overlays: readonly string[];
  };
}

function record(value: unknown, pointer: string): Record<string, unknown> {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    throw new PresetRejected(pointer, 'expected an object');
  }
  return value as Record<string, unknown>;
}

function num(source: Record<string, unknown>, key: string, pointer: string): number {
  const value = source[key];
  if (typeof value !== 'number' || !Number.isFinite(value)) {
    throw new PresetRejected(`${pointer}/${key}`, `expected a finite number, got ${JSON.stringify(value)}`);
  }
  return value;
}

function str(source: Record<string, unknown>, key: string, pointer: string): string {
  const value = source[key];
  if (typeof value !== 'string') {
    throw new PresetRejected(`${pointer}/${key}`, `expected a string, got ${JSON.stringify(value)}`);
  }
  return value;
}

function integer(source: Record<string, unknown>, key: string, pointer: string): number {
  const value = num(source, key, pointer);
  if (!Number.isInteger(value)) {
    throw new PresetRejected(`${pointer}/${key}`, `expected an integer, got ${String(value)}`);
  }
  return value;
}

/**
 * Parse and check a preset JSON object.
 *
 * `json` is the PARSED form of the bytes `GET /api/presets/{id}` served. The
 * byte-identity contract of decision 7(a) is proved by the sha256 shown beside
 * the name, not by this function — parsing for use and hashing for display are
 * two different jobs and `api.getPresetSource` keeps them apart.
 */
export function readLivePreset(json: unknown): LivePreset {
  const root = record(json, '');
  const id = str(root, 'id', '');
  const name = str(root, 'name', '');
  const analysis = record(root['analysis'], '/analysis');
  const display = record(root['display'], '/display');
  const window = record(analysis['window'], '/analysis/window');
  const resolution = record(analysis['resolution'], '/analysis/resolution');

  const windowName = str(window, 'name', '/analysis/window');
  if (!PRESET_WINDOW_FAMILIES.includes(windowName)) {
    throw new PresetRejected(
      '/analysis/window/name',
      `${JSON.stringify(windowName)} is not one of preset-schema.md §4.3's families ` +
        `(${PRESET_WINDOW_FAMILIES.join(', ')}). ` +
        "`rect` is admitted by the golden manifest for calibration tones and is NEVER a preset family " +
        '(ADR 0006 consequence (c)): a loader that meets it must reject the preset.',
    );
  }
  const form = str(window, 'form', '/analysis/window');
  if (form !== 'periodic') {
    throw new PresetRejected(
      '/analysis/window/form',
      `expected "periodic", got ${JSON.stringify(form)}. ADR 0006 D1 rejects the symmetric form outright: ` +
        'its NENBW no longer equals the closed form the presets ship (1.500366 instead of 1.5 for hann), ' +
        'so every level readout would acquire a small N-dependent bias.',
    );
  }

  const coefficients = window['coefficients'];
  if (!Array.isArray(coefficients) || coefficients.some((c) => typeof c !== 'number')) {
    throw new PresetRejected('/analysis/window/coefficients', 'expected an array of numbers');
  }
  // --- rule V8 --------------------------------------------------------------
  const table = windowCoefficients(windowName);
  const mismatch =
    table.length !== coefficients.length ||
    table.some((a, k) => a !== (coefficients[k] as number));
  if (mismatch) {
    throw new PresetRejected(
      '/analysis/window/coefficients',
      `they disagree with this build's §4.3 table for ${JSON.stringify(windowName)}: preset ` +
        `[${(coefficients as number[]).join(', ')}] vs table [${table.join(', ')}]. ADR 0006 D1 makes the ` +
        'COEFFICIENTS the contract — routing through the NAME instead hides a 0.0163 difference for the ' +
        'nuttall family — so a disagreement is refused rather than resolved in either direction.',
    );
  }

  const spectrumType = str(analysis, 'spectrum_type', '/analysis');
  const scaling: 'power_spectrum' | 'power_spectral_density' | null =
    spectrumType === 'power_spectrum'
      ? 'power_spectrum'
      : spectrumType === 'psd'
        ? 'power_spectral_density'
        : null;
  if (scaling === null) {
    throw new PresetRejected('/analysis/spectrum_type', `expected "power_spectrum" or "psd", got ${JSON.stringify(spectrumType)}`);
  }
  const dbReference = str(analysis, 'db_reference', '/analysis');
  if (dbReference !== 'dbfs_sine') {
    throw new PresetRejected(
      '/analysis/db_reference',
      `expected "dbfs_sine", got ${JSON.stringify(dbReference)} — the 3.01 dB trap of golden-files.md`,
    );
  }

  const smoothing = num(analysis, 'smoothing', '/analysis');
  if (!(smoothing >= 0) || !(smoothing < 1)) {
    throw new PresetRejected(
      '/analysis/smoothing',
      `expected [0, 1) — the weight of the PREVIOUS frame (ADR 0021 decision 7d) — got ${String(smoothing)}`,
    );
  }
  const dcBlockerHz = num(analysis, 'dc_blocker_hz', '/analysis');
  const holdRequested = str(analysis, 'hold', '/analysis');
  // `min` is a preset value (`room_noise_floor`) that W1 does not render: a
  // minimum hold is a noise-floor readout and it arrives with the waterfall in
  // W2. Mapped to `none` and REPORTED as `holdRequested`, so the panel can say
  // so — a silent map would be a preset displayed as something it is not.
  const hold: 'none' | 'peak' = holdRequested === 'peak' ? 'peak' : 'none';

  const freqScaleRaw = str(display, 'freq_scale', '/display');
  if (freqScaleRaw !== 'log' && freqScaleRaw !== 'linear') {
    throw new PresetRejected('/display/freq_scale', `expected "log" or "linear", got ${JSON.stringify(freqScaleRaw)}`);
  }
  const refresh = display['refresh_hz_target'];
  const overlaysRaw = display['overlays'];
  if (!Array.isArray(overlaysRaw) || !overlaysRaw.every((o) => typeof o === 'string')) {
    throw new PresetRejected('/display/overlays', 'expected an array of strings');
  }
  const overlays: readonly string[] = Object.freeze([...(overlaysRaw as string[])]);

  return {
    id,
    name,
    sampleRateHz: integer(analysis, 'sample_rate_hz', '/analysis'),
    fftSize: integer(analysis, 'fft_size', '/analysis'),
    hopSamples: integer(resolution, 'hop_samples', '/analysis/resolution'),
    intervalMs: num(analysis, 'interval_ms', '/analysis'),
    smoothing,
    averaging: str(analysis, 'averaging', '/analysis'),
    scaling,
    dcBlockerHz: dcBlockerHz > 0 ? dcBlockerHz : null,
    hold,
    holdRequested,
    windowName,
    windowCoefficients: coefficients as readonly number[],
    display: {
      freqMinHz: num(display, 'freq_min_hz', '/display'),
      freqMaxHz: num(display, 'freq_max_hz', '/display'),
      freqScale: freqScaleRaw,
      dbFloorDbfs: num(display, 'db_floor_dbfs', '/display'),
      dbCeilingDbfs: num(display, 'db_ceiling_dbfs', '/display'),
      refreshHzTarget: typeof refresh === 'number' ? refresh : null,
      overlays,
    },
  };
}

/**
 * The preset as a `SpectrumConfig` — `spectrum_config_from_preset`'s TypeScript
 * twin, and the one place the mapping is written.
 *
 * `window_length_samples == fft_size`: no preset zero-pads, and ADR 0006's
 * `enbw_bins` closed form is stated for the un-padded transform. The
 * `normalization` is `S1` and the reference is a full-scale `sine` for every
 * preset — those two are ADR 0006 D2 and D3, not preset fields, and the schema
 * deliberately does not offer them (ADR 0010: the preset names what it DISPLAYS,
 * ADR 0006 fixes the constants).
 */
export function spectrumConfigFromPreset(preset: LivePreset): SpectrumConfig {
  return {
    window: preset.windowName,
    window_length_samples: preset.fftSize,
    fftbins: true,
    fft_size: preset.fftSize,
    normalization: 'S1',
    scaling: preset.scaling,
    dbfs_reference: 'sine',
    int16_scale: DEFAULT_INT16_SCALE,
    // IEEE double throughout, which is what makes this a second INDEPENDENT
    // instrument rather than a re-run of the device's float32 (ADR 0021 D2).
    dtype: 'float64',
  };
}

/** Columns per second the preset asks for: `fs/hop`, the rate the Worker will actually produce. */
export function expectedColumnsPerSecond(preset: LivePreset): number {
  return preset.sampleRateHz / preset.hopSamples;
}
