//
// The spectrogram colormap, read from the committed LUT — not converted here.
//
// ADR 0011's whole argument is that the ramp is designed *in* RGB565 rather than
// converted to it: per-channel rounding minimises channel error instead of
// perceptual error, does not know the map must stay luminance-monotone, and
// collapses a smooth dB ramp into flat runs whose boundaries read as contour
// lines — spurious structure, in the one instrument that must not invent any.
//
// That argument only holds if the browser and the watch show the SAME 256 words.
// So this module imports `dsp/colormaps/cividis_rgb565.json`, which
// `python-scripts/gen_colormap_lut.py --json` produced from the same dynamic
// program that will emit the firmware header, and expands 565 → 888 exactly the
// way the shader would. It never computes a colormap of its own.
// ---------------------------------------------------------------------------

import lut from '../../../../dsp/colormaps/cividis_rgb565.json';

export interface Colormap {
  readonly name: string;
  readonly entries: number;
  /** RGBA8, 4 bytes per entry, ready for `texImage2D`. */
  readonly rgba: Uint8Array;
  /** Distinct RGB565 words — ADR 0011's banding measure, carried for display. */
  readonly distinct: number;
  readonly maxStepDe76: number;
}

/**
 * 5/6/5 → 8/8/8 by BIT REPLICATION, not by `<< 3`.
 *
 * `(r5 << 3)` maps 31 to 248, so full red never reaches 255 and the top of the
 * ramp is dimmer than the map says. Replicating the high bits into the low ones
 * — `(r5 << 3) | (r5 >> 2)` — maps 0→0 and 31→255 and is the expansion every
 * panel driver and every shader uses. Getting this wrong is invisible in the
 * middle of the ramp and wrong at both ends, which is the worst place for it.
 */
export function expand565(word: number): [number, number, number] {
  const r5 = (word >> 11) & 0x1f;
  const g6 = (word >> 5) & 0x3f;
  const b5 = word & 0x1f;
  return [(r5 << 3) | (r5 >> 2), (g6 << 2) | (g6 >> 4), (b5 << 3) | (b5 >> 2)];
}

function build(): Colormap {
  const words = lut.lut as number[];
  const rgba = new Uint8Array(words.length * 4);
  words.forEach((word, i) => {
    const [r, g, b] = expand565(word);
    rgba[i * 4] = r;
    rgba[i * 4 + 1] = g;
    rgba[i * 4 + 2] = b;
    rgba[i * 4 + 3] = 255;
  });
  return {
    name: lut.map,
    entries: words.length,
    rgba,
    distinct: lut.metrics.distinct,
    maxStepDe76: lut.metrics.max_step_de76,
  };
}

export const COLORMAP: Colormap = build();
